contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 seedAmount) public payable {
        require(address(this).balance >= seedAmount);

        c.seedMarket{value: seedAmount}(1);
        c.getFreeKilo();

        uint256 beforeKilos = c.Kilos(address(this));
        uint256 beforeClaimed = c.claimedDrugs(address(this));
        uint256 beforeLastCollect = c.lastCollect(address(this));
        uint256 beforeNow = block.timestamp;

        c.collectDrugs(address(0));

        uint256 pending = c.getDrugsSinceLastCollect(address(this));
        uint256 secondsPassed = beforeNow - beforeLastCollect;
        if (secondsPassed > c.DRUGS_TO_PRODUCE_1KILO()) {
            secondsPassed = c.DRUGS_TO_PRODUCE_1KILO();
        }
        uint256 expectedPending = beforeKilos * secondsPassed;
        uint256 expectedAdded = expectedPending / c.DRUGS_TO_PRODUCE_1KILO();

        assert(c.claimedDrugs(address(this)) == 0 &&
               c.Kilos(address(this)) == beforeKilos + expectedAdded &&
               c.lastCollect(address(this)) == block.timestamp &&
               c.claimedDrugs(address(0)) == expectedPending / 5 &&
               c.marketDrugs() == 1 + expectedPending / 10);
    }

    receive() external payable {}
}

