contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 seedAmount) public payable {
        require(address(this).balance >= seedAmount);
        require(address(this).balance >= 1);

        // Initialize the market so collectDrugs does not revert.
        c.seedMarket{value: seedAmount}(1);

        // Give the caller some Kilos so getMyDrugs is positive.
        c.getFreeKilo();

        // Record the timestamp after setup but before the deciding call.
        uint256 beforeTimestamp = block.timestamp;

        // The deciding call: collectDrugs with no referrer.
        c.collectDrugs(address(0));

        // Read observable state after the call.
        uint256 claimedAfter = c.claimedDrugs(address(this));
        uint256 lastCollectAfter = c.lastCollect(address(this));

        assert(claimedAfter == 0 && lastCollectAfter == beforeTimestamp);
    }

    receive() external payable {}
}

